-- =====================================================================
-- culture_members — перенос шестнадцати артистов театра «Жастар»
--
-- Источник — src/data/teatr.ts, собранный из презентационного пакета
-- учреждения. Поля пакета легли так: специальность → role_*, учебное
-- заведение → education_*, уровень → level_*, регалии → note_*.
--
-- У троих в пакете нет карточки — они идут только именем, с пустыми полями и
-- без фотографии. Это не потеря при переносе: их там и не было.
--
-- has_higher_education выведён из уровня («Высшее» → true), а не сравнивается
-- с текстом на лету: текст редактируемый, флаг — нет.
--
-- Фотографии остаются ссылками на /images/teatr/members/*, файлы лежат в
-- приложении, поэтому path = null и удаление артиста ничего из бакета не сотрёт.
--
-- ИДЕМПОТЕНТНОСТЬ. Вставка пропускается целиком, если у театра уже есть хоть
-- один артист.
-- =====================================================================

begin;

with club as (
  select c.id, c.organization_id
  from public.culture_clubs c
  join public.organizations o on o.id = c.organization_id
  where o.slug = 'ken-zhylyoi' and c.slug = 'zhastar'
), incoming (name, name_kk, name_ru, role_kk, role_ru, education_kk, education_ru,
             level_kk, level_ru, has_higher_education, note_kk, note_ru,
             images, sort_order) as (
  values
  ('Қопал Мағрипа Қопалқызы', 'Қопал Мағрипа Қопалқызы', 'Қопал Мағрипа Қопалқызы', 'Хореография', 'Хореография', 'Қызылорда «Болашақ» университеті; Батыс Қазақстан инженерлік-гуманитарлық университеті', 'Кызылординский университет «Болашақ»; Западно-Казахстанский инженерно-гуманитарный университет', 'Жоғары', 'Высшее', true, 'Мәдениет саласының үздігі, Жылыой ауданының құрметті азаматы', 'Отличник сферы культуры, почётный гражданин Жылыойского района', '[{"url":"/images/teatr/members/member-01.jpeg","path":null}]'::jsonb, 10),
  ('Жиенбаева Назгүл Өмірғалиқызы', 'Жиенбаева Назгүл Өмірғалиқызы', 'Жиенбаева Назгүл Өмірғалиқызы', 'Дәстүрлі ән өнері', 'Традиционное песенное искусство', 'Х. Досмұхамедов атындағы Атырау мемлекеттік университеті', 'Атырауский государственный университет имени Х. Досмухамедова', 'Жоғары', 'Высшее', true, 'Көркемдік жетекші', 'Художественный руководитель', '[{"url":"/images/teatr/members/member-02.jpeg","path":null}]'::jsonb, 20),
  ('Тасымова Айнұр Қанатқызы', 'Тасымова Айнұр Қанатқызы', 'Тасымова Айнұр Қанатқызы', 'Театр және кино артисі', 'Артистка театра и кино', 'Т. Қ. Жүргенов атындағы Қазақ ұлттық өнер академиясы', 'Казахская национальная академия искусств имени Т. К. Жургенова', 'Жоғары', 'Высшее', true, null, null, '[{"url":"/images/teatr/members/member-03.jpeg","path":null}]'::jsonb, 30),
  ('Аманқосов Бекет', 'Аманқосов Бекет', 'Аманқосов Бекет', 'Эстрада вокалы мұғалімі', 'Преподаватель эстрадного вокала', 'Д. Нұрпейісова атындағы халық музыкасы академиясы, Атырау музыкалық колледжі', 'Академия народной музыки имени Д. Нурпеисовой, Атырауский музыкальный колледж', 'Орташа', 'Среднее', false, null, null, '[{"url":"/images/teatr/members/member-04.jpeg","path":null}]'::jsonb, 40),
  ('Бақытжанұлы Айбол', 'Бақытжанұлы Айбол', 'Бақытжанұлы Айбол', 'Дәстүрлі музыка өнері', 'Традиционное музыкальное искусство', 'Х. Досмұхамедов атындағы Атырау мемлекеттік университеті', 'Атырауский государственный университет имени Х. Досмухамедова', 'Жоғары', 'Высшее', true, null, null, '[{"url":"/images/teatr/members/member-05.jpeg","path":null}]'::jsonb, 50),
  ('Нұрханова Жайна Мергенқызы', 'Нұрханова Жайна Мергенқызы', 'Нұрханова Жайна Мергенқызы', 'Музыка және ән', 'Музыка и пение', 'Х. Досмұхамедов атындағы Атырау мемлекеттік университеті', 'Атырауский государственный университет имени Х. Досмухамедова', 'Жоғары', 'Высшее', true, null, null, '[{"url":"/images/teatr/members/member-06.jpeg","path":null}]'::jsonb, 60),
  ('Ержанов Жақсылық', 'Ержанов Жақсылық', 'Ержанов Жақсылық', 'Тасымалдауды ұйымдастыру', 'Организация перевозок', 'Атырау бизнес және құқық колледжі', 'Атырауский колледж бизнеса и права', 'Орташа', 'Среднее', false, null, null, '[{"url":"/images/teatr/members/member-07.jpeg","path":null}]'::jsonb, 70),
  ('Орынбасарова Аймира Мэлсқызы', 'Орынбасарова Аймира Мэлсқызы', 'Орынбасарова Аймира Мэлсқызы', 'Аудармашы', 'Переводчик', 'Х. Досмұхамедов атындағы Атырау мемлекеттік университеті; Тұран колледжі, «Аударма ісі»', 'Атырауский государственный университет имени Х. Досмухамедова; колледж «Туран», «Переводческое дело»', 'Жоғары', 'Высшее', true, null, null, '[{"url":"/images/teatr/members/member-08.jpeg","path":null}]'::jsonb, 80),
  ('Жұмағалиев Ерғанат Ержанұлы', 'Жұмағалиев Ерғанат Ержанұлы', 'Жұмағалиев Ерғанат Ержанұлы', 'Халық әні, терме', 'Народная песня, терме', 'Х. Досмұхамедов атындағы Атырау мемлекеттік университеті', 'Атырауский государственный университет имени Х. Досмухамедова', 'Жоғары', 'Высшее', true, null, null, '[{"url":"/images/teatr/members/member-09.jpeg","path":null}]'::jsonb, 90),
  ('Амандық Әлібек Аманжанұлы', 'Амандық Әлібек Аманжанұлы', 'Амандық Әлібек Аманжанұлы', 'Заңгер', 'Юрист', 'ҚазИТУ; Қ. Жұбанов атындағы АӨМУ', 'КазИТУ; АРГУ имени К. Жубанова', 'Жоғары', 'Высшее', true, null, null, '[{"url":"/images/teatr/members/member-10.jpeg","path":null}]'::jsonb, 100),
  ('Асанов Махамбет Жұбандықұлы', 'Асанов Махамбет Жұбандықұлы', 'Асанов Махамбет Жұбандықұлы', 'Мұнай және газ кен орындарын пайдалану, техник-технолог', 'Эксплуатация нефтегазовых месторождений, техник-технолог', 'Т. Байсырымов атындағы Құлсары гуманитарлық-техникалық колледжі (2018–2022)', 'Кульсаринский гуманитарно-технический колледж имени Т. Байсырымова (2018–2022)', 'Арнайы орта', 'Среднее специальное', false, null, null, '[{"url":"/images/teatr/members/member-11.jpeg","path":null}]'::jsonb, 110),
  ('Қоңыров Асқар', 'Қоңыров Асқар', 'Қоңыров Асқар', null, null, null, null, 'Орта', 'Среднее', false, null, null, '[{"url":"/images/teatr/members/member-12.jpeg","path":null}]'::jsonb, 120),
  ('Жұмағалиева Нұргүл', 'Жұмағалиева Нұргүл', 'Жұмағалиева Нұргүл', 'Дәстүрлі өнер', 'Традиционное искусство', 'Х. Досмұхамедов атындағы Атырау мемлекеттік университеті', 'Атырауский государственный университет имени Х. Досмухамедова', 'Жоғары', 'Высшее', true, null, null, '[{"url":"/images/teatr/members/member-13.jpeg","path":null}]'::jsonb, 130),
  ('Елеуова Мөлдір Дәуренқызы', 'Елеуова Мөлдір Дәуренқызы', 'Елеуова Мөлдір Дәуренқызы', null, null, null, null, null, null, false, null, null, '[]'::jsonb, 140),
  ('Орынғалиев Еламан', 'Орынғалиев Еламан', 'Орынғалиев Еламан', null, null, null, null, null, null, false, null, null, '[]'::jsonb, 150),
  ('Каманова Жанаргүл', 'Каманова Жанаргүл', 'Каманова Жанаргүл', null, null, null, null, null, null, false, null, null, '[]'::jsonb, 160)
)
insert into public.culture_members (
  organization_id, club_id, name, name_kk, name_ru, role_kk, role_ru,
  education_kk, education_ru, level_kk, level_ru, has_higher_education,
  note_kk, note_ru, images, sort_order, is_active
)
select club.organization_id, club.id, i.name, i.name_kk, i.name_ru, i.role_kk, i.role_ru,
       i.education_kk, i.education_ru, i.level_kk, i.level_ru, i.has_higher_education,
       i.note_kk, i.note_ru, i.images, i.sort_order, true
from incoming i cross join club
where not exists (
  select 1 from public.culture_members m where m.club_id = club.id
);

commit;
